package io.knowledgebrain.media;
import java.time.*;import java.util.*;import jakarta.servlet.http.Cookie;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LearningMediaReferenceTest {
 MediaStore store;SpaceAuthorizationClient auth;ObjectStorage storage;LearningMediaReferenceController api;UUID space,actor,file;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();actor=ids.next();file=ids.next();store=mock(MediaStore.class);auth=mock(SpaceAuthorizationClient.class);storage=mock(ObjectStorage.class);var metrics=new SimpleMeterRegistry();api=new LearningMediaReferenceController(store,new MediaController(store,storage,auth,metrics,"https://localhost:8443"),metrics);when(auth.authorize(eq(space),eq("a".repeat(43)),eq(false),anyString())).thenReturn(actor);}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));return r;}
 @Test void freshOwnerAuthorityAndAvailableOnlyMetadataExcludeStorageCredentials(){when(store.available(space,file)).thenReturn(new MediaStore.Info(file,space,"AVAILABLE",2,"proof.pdf","application/pdf",42,"a".repeat(64),Instant.now(),Instant.now()));var response=api.get(space,file,request());assertEquals("no-store",response.getHeaders().getCacheControl());assertEquals(actor,response.getBody().principalId());assertEquals(2,response.getBody().version());assertEquals("a".repeat(64),response.getBody().sha256());api.get(space,file,request());verify(auth,times(2)).authorize(eq(space),anyString(),eq(false),anyString());verifyNoInteractions(storage);}
 @Test void strictReadDenialAndUnfinishedUploadsNeverYieldReference(){var query=request();query.addParameter("url","spoof");assertEquals(400,assertThrows(ResponseStatusException.class,()->api.get(space,file,query)).getStatusCode().value());var body=request();body.setContent("{}".getBytes());assertEquals(400,assertThrows(ResponseStatusException.class,()->api.get(space,file,body)).getStatusCode().value());when(auth.authorize(eq(space),anyString(),eq(false),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));assertEquals(403,assertThrows(ResponseStatusException.class,()->api.get(space,file,request())).getStatusCode().value());verifyNoInteractions(store,storage);reset(auth);when(auth.authorize(eq(space),anyString(),eq(false),anyString())).thenReturn(actor);when(store.available(space,file)).thenThrow(new ResponseStatusException(HttpStatus.CONFLICT));assertEquals(409,assertThrows(ResponseStatusException.class,()->api.get(space,file,request())).getStatusCode().value());}
}
